#!/usr/bin/env python3
"""
Update docs/determinism-benchmark-results.md from JSON artifacts.
"""
import glob
import json
from pathlib import Path

def main():
    docs_path = Path("docs/determinism-benchmark-results.md")
    
    if not docs_path.exists():
        print("docs/determinism-benchmark-results.md not found.")
        return
        
    results = {}
    
    # Iterate over JSON artifact files generated by CI
    for filename in glob.glob("results-*.json"):
        with open(filename, "r") as f:
            data = json.load(f)
            lang = data.get("language")
            # Usually results-{language}-{os}.json
            # Extract OS from filename
            parts = Path(filename).stem.split('-')
            os_name = "-".join(parts[2:]) # e.g. results-python-ubuntu-latest.json -> ubuntu-latest
            
            if lang not in results:
                results[lang] = {}
            results[lang][os_name] = data
            
    if not results:
        print("No results-*.json files found.")
        return
        
    print(f"Loaded results for {len(results)} languages.")
    
    # Read template doc and find the table boundary
    content = docs_path.read_text()
    lines = content.splitlines()
    
    try:
        start_idx = lines.index("<!-- RESULTS_TABLE_START -->")
        end_idx = lines.index("<!-- RESULTS_TABLE_END -->")
    except ValueError:
        print("Could not find table markers in the docs file.")
        return
        
    # Generate new table
    new_table = [
        "| Language | OS | Deterministic? | p50 latency | p99 latency | Hash |",
        "|---|---|---|---|---|---|"
    ]
    
    for lang, os_data in sorted(results.items()):
        for os_name, data in sorted(os_data.items()):
            det = "✅ YES" if data.get("deterministic") else "❌ NO"
            p50 = f"{data.get('p50_ms')}ms"
            p99 = f"{data.get('p99_ms')}ms"
            # Get the first hash or "N/A"
            hashes = data.get("hashes")
            h = hashes[0][:12] if hashes else "N/A"
            new_table.append(f"| {lang} | {os_name} | {det} | {p50} | {p99} | `{h}` |")
            
    # Inject
    new_lines = lines[:start_idx + 1] + new_table + lines[end_idx:]
    docs_path.write_text("\n".join(new_lines) + "\n")
    print("Updated docs/determinism-benchmark-results.md successfully.")

if __name__ == "__main__":
    main()
